const require_index = require("../useIsomorphicLayoutEffect/index.js");
let react = require("react");
//#region src/useLatest/index.ts
const useLatest = (value) => {
	const ref = (0, react.useRef)(value);
	require_index.useIsomorphicLayoutEffect(() => {
		ref.current = value;
	}, [value]);
	return ref;
};
//#endregion
exports.useLatest = useLatest;
